import React, { useState } from "react";
import { useParams, Link } from "react-router-dom";
import { Box, Typography, Button, TextField, Chip, CircularProgress, Collapse, Alert } from "@mui/material";
import simulations from "./Simulations";
import { ZB_COLORS } from "./theme";
import { generateCertificate } from "./Certificate";
import { getAIFeedback } from "./aiFeedback";
import { notifySimulationComplete } from "./notifications";

const CheckIcon = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" style={{ verticalAlign: "middle", marginRight: 6 }}>
    <circle cx="8" cy="8" r="8" fill="#4caf50" fillOpacity="0.15" />
    <path d="M5 8l2 2 4-4" stroke="#4caf50" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

const SparkIcon = () => (
  <svg width="14" height="14" viewBox="0 0 14 14" fill="none" style={{ verticalAlign: "middle", marginRight: 5 }}>
    <path d="M7 1l1.5 4H13l-3.5 2.5L11 12 7 9.5 3 12l1.5-4.5L1 5h4.5L7 1z" fill="#ffd600" fillOpacity="0.9" />
  </svg>
);

export default function SimulationRunner({ profile }) {
  const { simId } = useParams();
  const sim = simulations.find(s => s.id === simId);
  const [activeStep, setActiveStep] = useState(0);
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [showModel, setShowModel] = useState({});
  const [aiFeedback, setAIFeedback] = useState({});
  const [loadingFeedback, setLoadingFeedback] = useState({});
  const [taskSubmitted, setTaskSubmitted] = useState({});

  if (!sim) {
    return (
      <Box sx={{ textAlign: "center", py: 10 }}>
        <Typography variant="h5" sx={{ color: "#fff", mb: 2 }}>Simulation not found</Typography>
        <Button component={Link} to="/simulations" variant="contained">Back to simulations</Button>
      </Box>
    );
  }

  const task = sim.tasks[activeStep];
  const isLast = activeStep === sim.tasks.length - 1;

  const handleSubmitTask = async () => {
    setTaskSubmitted(prev => ({ ...prev, [task.id]: true }));
  };

  const handleGetAIFeedback = async () => {
    if (!answers[task.id]?.trim()) return;
    setLoadingFeedback(prev => ({ ...prev, [task.id]: true }));
    const feedback = await getAIFeedback(task.question, answers[task.id], task.modelAnswer, sim.title);
    setAIFeedback(prev => ({ ...prev, [task.id]: feedback }));
    setLoadingFeedback(prev => ({ ...prev, [task.id]: false }));
  };

  const handleNext = () => {
    if (isLast) {
      setSubmitted(true);
      if (profile) notifySimulationComplete(profile, sim);
    } else {
      setActiveStep(prev => prev + 1);
      window.scrollTo(0, 0);
    }
  };

  const handleDownloadCert = () => {
    generateCertificate(
      profile?.name || "ZBRIDGE Graduate",
      sim.title,
      sim.partner,
      new Date().toLocaleDateString("en-ZM", { year: "numeric", month: "long", day: "numeric" })
    );
  };

  if (submitted) {
    return (
      <Box sx={{ maxWidth: 640, mx: "auto", px: 2, py: 8, textAlign: "center" }}>
        <Box sx={{ width: 72, height: 72, borderRadius: "50%", background: "rgba(76,175,80,0.15)", display: "flex", alignItems: "center", justifyContent: "center", mx: "auto", mb: 3, fontSize: "2rem" }}>
          🎉
        </Box>
        <Typography variant="h4" sx={{ color: "#fff", mb: 1 }}>Simulation complete!</Typography>
        <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 1 }}>
          You've completed all {sim.tasks.length} tasks in
        </Typography>
        <Typography sx={{ color: ZB_COLORS.gold, fontFamily: "Sora", fontWeight: 600, fontSize: "1.1rem", mb: 3 }}>
          {sim.title}
        </Typography>

        {sim.partner && (
          <Box sx={{ background: "rgba(255,214,0,0.06)", border: "0.5px solid rgba(255,214,0,0.2)", borderRadius: "12px", p: 2, mb: 3 }}>
            <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 0.5 }}>
              In partnership with
            </Typography>
            <Typography sx={{ color: ZB_COLORS.gold, fontFamily: "Sora", fontWeight: 600 }}>
              {sim.partner}
            </Typography>
          </Box>
        )}

        <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5, maxWidth: 320, mx: "auto" }}>
          <Button
            variant="contained"
            size="large"
            onClick={handleDownloadCert}
            sx={{ py: 1.3, fontSize: "0.95rem" }}
          >
            📄 Download certificate
          </Button>
          <Alert severity="info" sx={{ textAlign: "left", fontSize: "0.8rem", background: "rgba(33,150,243,0.1)", border: "0.5px solid rgba(33,150,243,0.3)", color: "rgba(255,255,255,0.8)" }}>
            Add your certificate to your LinkedIn profile and CV — employers recognise ZBRIDGE simulations.
          </Alert>
          <Button component={Link} to="/simulations" variant="outlined" sx={{ borderColor: ZB_COLORS.border, color: "rgba(255,255,255,0.7)" }}>
            Try another simulation
          </Button>
          <Button component={Link} to="/dashboard" sx={{ color: ZB_COLORS.textMuted, fontSize: "0.875rem" }}>
            Back to dashboard
          </Button>
        </Box>
      </Box>
    );
  }

  return (
    <Box sx={{ maxWidth: 800, mx: "auto", px: { xs: 2, md: 3 }, py: { xs: 4, md: 6 } }}>
      {/* Header */}
      <Box sx={{ mb: 4 }}>
        <Button component={Link} to="/simulations" sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", fontSize: "0.85rem", mb: 1.5, pl: 0 }}>
          ← Back to simulations
        </Button>
        <Box sx={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 2, flexWrap: "wrap" }}>
          <Box>
            <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>{sim.title}</Typography>
            <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", fontSize: "0.875rem" }}>{sim.description}</Typography>
          </Box>
          {sim.partner && (
            <Chip
              label={"Partner: " + sim.partner}
              size="small"
              sx={{ background: "rgba(255,214,0,0.1)", color: ZB_COLORS.gold, border: "0.5px solid rgba(255,214,0,0.3)", fontFamily: "DM Sans", fontSize: "0.72rem", whiteSpace: "nowrap" }}
            />
          )}
        </Box>
      </Box>

      {/* Step indicators */}
      <Box sx={{ display: "flex", gap: 1, mb: 4, flexWrap: "wrap" }}>
        {sim.tasks.map((t, i) => (
          <Box
            key={t.id}
            onClick={() => i <= activeStep && setActiveStep(i)}
            sx={{
              width: 32, height: 32, borderRadius: "50%",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: "0.78rem", fontFamily: "DM Sans", fontWeight: 600,
              cursor: i <= activeStep ? "pointer" : "default",
              background: i < activeStep ? "#4caf50" : i === activeStep ? ZB_COLORS.gold : "rgba(255,255,255,0.07)",
              color: i <= activeStep ? "#0a0a0a" : "rgba(255,255,255,0.4)",
              border: i === activeStep ? "none" : "0.5px solid rgba(255,255,255,0.1)",
              transition: "all 0.2s",
            }}
          >
            {i < activeStep ? "✓" : i + 1}
          </Box>
        ))}
        <Typography sx={{ fontSize: "0.78rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", ml: 1, alignSelf: "center" }}>
          Task {activeStep + 1} of {sim.tasks.length}
        </Typography>
      </Box>

      {/* Progress bar */}
      <Box sx={{ mb: 4 }}>
        <Box sx={{ display: "flex", justifyContent: "space-between", mb: 1 }}>
          <Typography sx={{ fontSize: "0.78rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>
            {Math.round((activeStep / sim.tasks.length) * 100)}% complete
          </Typography>
          <Typography sx={{ fontSize: "0.78rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>
            {sim.duration}
          </Typography>
        </Box>
        <Box sx={{ height: 4, background: ZB_COLORS.border, borderRadius: 2, overflow: "hidden" }}>
          <Box sx={{ width: `${(activeStep / sim.tasks.length) * 100}%`, height: "100%", background: ZB_COLORS.gold, borderRadius: 2, transition: "width 0.4s ease" }} />
        </Box>
      </Box>

      {/* Task Card */}
      <Box sx={{ background: ZB_COLORS.navyMid, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "16px", p: { xs: 2.5, md: 4 }, mb: 2 }}>
        <Chip
          label={"Task " + (activeStep + 1)}
          size="small"
          sx={{ background: "rgba(255,214,0,0.1)", color: ZB_COLORS.gold, border: "0.5px solid rgba(255,214,0,0.3)", fontFamily: "DM Sans", mb: 2 }}
        />
        <Typography sx={{ color: "#fff", fontFamily: "DM Sans", fontSize: "1rem", lineHeight: 1.7, mb: 3 }}>
          {task.question}
        </Typography>

        <TextField
          label="Your answer"
          fullWidth
          multiline
          minRows={4}
          value={answers[task.id] || ""}
          onChange={e => setAnswers({ ...answers, [task.id]: e.target.value })}
          disabled={taskSubmitted[task.id]}
          sx={{ mb: 2 }}
        />

        {task.fileType && (
          <Box sx={{ mb: 3, p: 1.5, background: "rgba(255,255,255,0.03)", borderRadius: "8px", border: `0.5px solid ${ZB_COLORS.border}` }}>
            <Typography sx={{ fontSize: "0.78rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 1 }}>
              Optional: attach a supporting file ({task.fileType.toUpperCase()})
            </Typography>
            <input type="file" accept={task.fileType.split(",").map(t => "." + t.trim()).join(",")} style={{ color: "rgba(255,255,255,0.5)", fontFamily: "DM Sans", fontSize: "0.8rem" }} />
          </Box>
        )}

        {/* Action buttons */}
        <Box sx={{ display: "flex", gap: 1.5, flexWrap: "wrap", mb: 2 }}>
          {!taskSubmitted[task.id] && (
            <Button
              variant="contained"
              onClick={handleSubmitTask}
              disabled={!answers[task.id]?.trim()}
              sx={{ fontSize: "0.875rem" }}
            >
              <CheckIcon /> Submit answer
            </Button>
          )}

          {taskSubmitted[task.id] && !aiFeedback[task.id] && (
            <Button
              onClick={handleGetAIFeedback}
              disabled={loadingFeedback[task.id]}
              sx={{
                background: "rgba(255,214,0,0.1)",
                color: ZB_COLORS.gold,
                border: "0.5px solid rgba(255,214,0,0.3)",
                borderRadius: "8px",
                fontSize: "0.875rem",
                "&:hover": { background: "rgba(255,214,0,0.18)" },
              }}
            >
              {loadingFeedback[task.id] ? <CircularProgress size={16} sx={{ color: ZB_COLORS.gold, mr: 1 }} /> : <SparkIcon />}
              {loadingFeedback[task.id] ? "Getting feedback…" : "Get AI feedback"}
            </Button>
          )}

          {taskSubmitted[task.id] && (
            <Button
              onClick={() => setShowModel(prev => ({ ...prev, [task.id]: !prev[task.id] }))}
              sx={{
                background: "rgba(255,255,255,0.05)",
                color: "rgba(255,255,255,0.65)",
                border: `0.5px solid ${ZB_COLORS.border}`,
                borderRadius: "8px",
                fontSize: "0.875rem",
                "&:hover": { background: "rgba(255,255,255,0.09)" },
              }}
            >
              {showModel[task.id] ? "Hide model answer" : "See model answer"}
            </Button>
          )}
        </Box>

        {/* AI Feedback panel */}
        <Collapse in={!!aiFeedback[task.id]}>
          <Box sx={{ background: "rgba(255,214,0,0.06)", border: "0.5px solid rgba(255,214,0,0.2)", borderRadius: "12px", p: 2.5, mb: 2 }}>
            <Box sx={{ display: "flex", alignItems: "center", mb: 1.5 }}>
              <SparkIcon />
              <Typography sx={{ color: ZB_COLORS.gold, fontFamily: "Sora", fontWeight: 600, fontSize: "0.875rem" }}>
                AI Feedback
              </Typography>
            </Box>
            <Typography sx={{ color: "rgba(255,255,255,0.85)", fontFamily: "DM Sans", fontSize: "0.875rem", lineHeight: 1.7, whiteSpace: "pre-wrap" }}>
              {aiFeedback[task.id]}
            </Typography>
          </Box>
        </Collapse>

        {/* Model Answer panel */}
        <Collapse in={!!showModel[task.id]}>
          <Box sx={{ background: "rgba(76,175,80,0.06)", border: "0.5px solid rgba(76,175,80,0.2)", borderRadius: "12px", p: 2.5, mb: 2 }}>
            <Box sx={{ display: "flex", alignItems: "center", mb: 1.5 }}>
              <CheckIcon />
              <Typography sx={{ color: "#4caf50", fontFamily: "Sora", fontWeight: 600, fontSize: "0.875rem" }}>
                Model answer
              </Typography>
            </Box>
            <Typography sx={{ color: "rgba(255,255,255,0.8)", fontFamily: "DM Sans", fontSize: "0.875rem", lineHeight: 1.75 }}>
              {task.modelAnswer}
            </Typography>
          </Box>
        </Collapse>
      </Box>

      {/* Navigation */}
      <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        {activeStep > 0 ? (
          <Button onClick={() => setActiveStep(prev => prev - 1)} sx={{ color: ZB_COLORS.textMuted, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "8px", px: 2 }}>
            ← Previous
          </Button>
        ) : <Box />}

        <Button
          variant="contained"
          onClick={handleNext}
          disabled={!taskSubmitted[task.id]}
          sx={{ fontSize: "0.9rem", px: 3 }}
        >
          {isLast ? "Complete simulation →" : "Next task →"}
        </Button>
      </Box>

      {!taskSubmitted[task.id] && (
        <Typography sx={{ textAlign: "center", mt: 2, fontSize: "0.78rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>
          Submit your answer above to continue
        </Typography>
      )}
    </Box>
  );
}
